{
  "units": [
    {
      "quote": "(CT:CITZ-141; 03-10-2026)",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "This citation indicates the update source code and date of the FAM section and conveys no substantive duty, permission, or prohibition."
    },
    {
      "quote": "A material discrepancy is any name change that is not defined as immaterial in 8 FAM 403.1-5.",
      "scope_quotes": [],
      "kind": "definition",
      "meaning": "A material discrepancy is defined as any name change that does not fall under the definition of immaterial in 8 FAM 403.1-5."
    },
    {
      "quote": "The applicant must explain any material discrepancies between the name on the application and the name recorded in the evidence of U.S. citizenship/non-citizen U.S. nationality and the evidence of identity (see 22 CFR 51.25).",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "The applicant is required to provide an explanation for any material discrepancies between the name listed on the application and the name appearing on the evidence of citizenship/non-citizen U.S. nationality and the evidence of identity."
    },
    {
      "quote": "Material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submission of one or more of the documents listed in this section (see an exception for married names in 8 FAM 403.1-4(C)).",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Except for married names covered in 8 FAM 403.1-4(C), any material discrepancy between the application name, citizenship/non-citizen nationality evidence name, or identity evidence name must be documented by submitting one or more of the acceptable documents listed in the section."
    },
    {
      "quote": "(a) Name change orders; or",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):",
        "(1) Court orders or decrees:"
      ],
      "kind": "alternative",
      "meaning": "Per 22 CFR 51.25, a court order for a name change is an acceptable form of documentation to establish a material name change."
    },
    {
      "quote": "(b) Divorce decrees;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):",
        "(1) Court orders or decrees:"
      ],
      "kind": "alternative",
      "meaning": "Per 22 CFR 51.25, a divorce decree is an acceptable form of court order or decree to document a material name change."
    },
    {
      "quote": "(2) Certificates of naturalization;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Per 22 CFR 51.25, a certificate of naturalization is an acceptable document for establishing a material name change."
    },
    {
      "quote": "(3) Marriage certificates;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Per 22 CFR 51.25, a marriage certificate is an acceptable document to prove a material name change."
    },
    {
      "quote": "(4) Documentation demonstrating change of name by operation of state law; or",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Per 22 CFR 51.25, documentation proving a name change occurred by operation of state law is an acceptable means to document a material name change."
    },
    {
      "quote": "(5) Documentation of customary usage.",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Per 22 CFR 51.25, documentation showing customary usage is an acceptable means of documenting a material name change."
    },
    {
      "quote": "NOTE: Evidence of material name changes must be reviewed for evidence of counterfeiting or alteration (see 8 FAM 201.1)",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Adjudicators are obligated to examine submitted evidence of material name changes for signs of counterfeiting or alteration pursuant to 8 FAM 201.1."
    },
    {
      "quote": "The applicant may not continue to use a previous name after a material name change unless the name change documentation specifically permits the applicant to continue using that name (see 8 FAM 403.1-6 regarding “known as” names).",
      "scope_quotes": [],
      "kind": "prohibition",
      "meaning": "Following a material name change, an applicant is prohibited from continuing to use a previous name, unless the name change documentation contains specific authorization permitting continued use of that name."
    },
    {
      "quote": "The applicant's name is an integral part of her/his identity. Consequently, under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Under 22 CFR 51.23(c) and Department guidance, evidence of identity may be requested if necessary to establish the name that best identifies the applicant."
    },
    {
      "quote": "If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name.",
      "scope_quotes": [
        "Consequently, under 22 CFR 51.23(c), evidence of identity might be required in accordance with Department guidance to establish the name that best identifies the applicant:"
      ],
      "kind": "requirement",
      "meaning": "When an applicant applying on Form DS-11 underwent a material name change more than one year before applying and has not updated their ID, the passport specialist must suspend the application and demand acceptable ID in the new name."
    },
    {
      "quote": "If there is insufficient time to request that the applicant submit acceptable ID prior to urgent or emergency travel, a limited-validity passport may be issued in the requested name;",
      "scope_quotes": [
        "If the applicant has had a material name change more than one year prior to applying on form DS-11 but has not updated her/his ID to reflect the material name change, you must suspend the application to request an acceptable ID in the new name."
      ],
      "kind": "permission",
      "meaning": "If an applicant requires urgent or emergency travel and there is not enough time to request acceptable ID in the new name after a suspension under d(1), a limited-validity passport is permitted to be issued in the requested name."
    },
    {
      "quote": "The applicant generally will need the name change documentation to change the name on her/his ID.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "As a practical general rule, the applicant will need the name change documentation in order to update the name on their identification."
    },
    {
      "quote": "You must fully notate the name change documentation prior to returning the documentation, including that the documentation was \"seen and returned,\" to the applicant with the information request letter (IRL); and",
      "scope_quotes": [
        "The applicant generally will need the name change documentation to change the name on her/his ID."
      ],
      "kind": "requirement",
      "meaning": "Before sending name change documentation back to an applicant accompanied by an Information Request Letter (IRL), the specialist must make complete notations on the documentation, explicitly recording that it was 'seen and returned'."
    },
    {
      "quote": "Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name.",
      "scope_quotes": [],
      "kind": "exemption",
      "meaning": "Applicants who obtained a material name change within one year of submitting Form DS-11 are exempt from having to submit identification bearing the new name."
    },
    {
      "quote": "However, if the ID has not yet been changed, they must submit their name change documentation.",
      "scope_quotes": [
        "Applicants who have had a material name change within one year of applying on a form DS-11 do not need to submit ID in the new name."
      ],
      "kind": "requirement",
      "meaning": "If an applicant whose material name change occurred within one year has not yet updated their ID, they are required to submit their name change documentation."
    }
  ]
}
